import React, { useEffect, useState, useRef } from "react";
import DataTable from "react-data-table-component";
import { makeApiRequest } from "../axiosService/ApiCall";
import { toast, ToastContainer } from "react-toastify";
import { Modal, Button, Spinner } from "react-bootstrap";
import "react-toastify/dist/ReactToastify.css";
import eth from "../Assets/images/ethereum.png";
import usdt from "../Assets/images/usdt.png";
import btc from "../Assets/images/btc.png";
import sol from "../Assets/images/solana.png";
import ltc from "../Assets/images/litecoin.png";
import car from "../Assets/images/cardano.png";
import Select from "react-select";
import { enUS } from "date-fns/locale";
import { DateRange } from "react-date-range";
import { FaCalendarAlt, FaRegCopy } from "react-icons/fa";
import { MdRefresh } from "react-icons/md";
import { decryptData } from "../Auth/SecurityCrypto";
import axios from "axios";
const cryptoData = [
  { img: eth, textOne: "ETH", textTwo: "Ethereum" },
  { img: usdt, textOne: "USDT", textTwo: "Tether USDT" },
  { img: btc, textOne: "BTC", textTwo: "Bitcoin" },
  { img: sol, textOne: "SOL", textTwo: "Solana" },
  { img: ltc, textOne: "LTC", textTwo: "Litecoin" },
  { img: car, textOne: "ADA", textTwo: "Cardano" },
];

function Withdrawrequest() {
  const [userData, setUserData] = useState([]);
  // console.log('userData', userData);

  const [loading, setLoading] = useState(false);
  const [totalPages, setTotalPages] = useState(0);
  const [limit, setLimit] = useState(10);
  const [searchQuery, setSearchQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [showModal, setShowModal] = useState(false);
  const [selectedRow, setSelectedRow] = useState(null);
  const [type, setType] = useState("");
  const [totalItems, setTotalItems] = useState(0);
  const [selectedSymbol, setSelectedSymbol] = useState("");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [showCalendar, setShowCalendar] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [historyLoading, setHistoryLoading] = useState(true);
  const [resetPaginationToggle, setResetPaginationToggle] = useState(false);
  const [is_Refreshing, setIs_Refreshing] = useState(false);
  const [WithdrawEdit, setWithdrawEdit] = useState(0);
  // console.log("WithdrawEdit", WithdrawEdit);
  const [adminType, setAdminType] = useState("");
  const [reason, setReason] = useState("");

  const WithdrawrequestRes = async () => {
    try {
      let params = {
        url: "view-edit-GetData",
        method: "GET",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };
      const WithdrawrequestRes = await makeApiRequest(params);
      console.log("WithdrawrequestRes", WithdrawrequestRes);
      if (WithdrawrequestRes.status) {
        const response = WithdrawrequestRes.data;
        setWithdrawEdit(response.adminPermissions.userRequest.Edit);
        setAdminType(response.admin_type);
      } else {
        toast.error(WithdrawrequestRes.message);
        //console.log(WithdrawrequestRes.message);
      }
    } catch (error) {
      console.log(error);
    }

  };
  useEffect(() => {
    WithdrawrequestRes();
  }, []);
  const calendarRef = useRef(null);
  const [range, setRange] = useState([
    {
      startDate: new Date(),
      endDate: new Date(),
      key: "selection",
    },
  ]);
  const formatWithoutRounding = (value, decimals) => {
    try {
      const factor = Math.pow(10, decimals);
      return Math.floor(value * factor) / factor;
    } catch (error) {
      console.log(error);
    }
  };

  const userpower = (x) => {
    x = x.toString();

    if (x.includes("e-")) {
      const [num, exp] = x.split("e-");
      const e = parseInt(exp);
      const digits = num.replace(".", "");
      const result = "0." + "0".repeat(e - 1) + digits;
      return result;
    } else if (x.includes("e+")) {
      const [num, exp] = x.split("e+");
      const e = parseInt(exp);
      const [intPart, decPart = ""] = num.split(".");
      let fullNum = intPart + decPart;
      while (fullNum.length < intPart.length + e) {
        fullNum += "0";
      }
      const decimal =
        fullNum.slice(0, intPart.length + e) +
        "." +
        fullNum.slice(intPart.length + e);
      return decimal;
    }

    return x;
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (calendarRef.current && !calendarRef.current.contains(event.target)) {
        setShowCalendar(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const handleChange = (selectedOption) => {
    handleReset();
    setSelectedSymbol(selectedOption ? selectedOption.value : "");
  };

  const cryptoOptions = cryptoData.map((data) => ({
    value: data.textOne,
    label: (
      <div style={{ display: "flex", alignItems: "center" }}>
        <img
          src={data.img}
          alt={data.textOne}
          style={{ width: 20, height: 20, marginRight: 10 }}
        />
        {data.textOne}
      </div>
    ),
  }));

  const handleDateChange = (item) => {
    setRange([item.selection]);

    const formatDate = (date) => {
      return date.toLocaleDateString("en-CA");
    };

    setFromDate(formatDate(item.selection.startDate));
    setToDate(formatDate(item.selection.endDate));
    setCurrentPage(1);
  };

  const handleReset = async () => {
    setLimit(10);
    setCurrentPage(1);
    setResetPaginationToggle(!resetPaginationToggle);
  };

  const userRequest = async (page = 1) => {
    try {
      let queryParams = new URLSearchParams({
        symbol: selectedSymbol || "",
        search: searchQuery || "",
        fromDate: fromDate || "",
        toDate: toDate || "",
        page: page,
        limit: limit,
      }).toString();

      let params = {
        url: `user-withdrawRequest?${queryParams}`,
        method: "GET",
      };
      const resp = await makeApiRequest(params);
      if (resp.status) {
        setUserData(resp.data);
        setHistoryLoading(false);
        setTotalPages(resp.totalPages);
        setTotalItems(resp.totalItems);
      } else {
        setUserData([]);
        setHistoryLoading(false);
      }
    } catch (error) {
      console.log("error---", error);
      setHistoryLoading(false);
    }
  };

  useEffect(() => {
    userRequest(currentPage);
  }, [selectedSymbol, fromDate, toDate, currentPage, searchQuery, limit]);

  // const handleClearFilters = () => {

  //   setSearchQuery("");
  //   setSelectedSymbol("");
  //   setFromDate("");
  //   setToDate("");
  //   setRange([
  //     {
  //       startDate: new Date(),
  //       endDate: new Date(),
  //       key: "selection",
  //     },
  //   ]);
  //   setShowCalendar("")
  //   setCurrentPage(1);
  //   setLimit(10);

  //   userRequest(1);
  // };
  const handleClearFilters = async () => {
    setIsRefreshing(true);
    setSearchQuery("");
    setSelectedSymbol("");
    setFromDate("");
    setToDate("");
    setRange([
      {
        startDate: new Date(),
        endDate: new Date(),
        key: "selection",
      },
    ]);
    setShowCalendar("");
    setCurrentPage(1);
    setLimit(10);
    setIs_Refreshing(is_Refreshing ? false : true);

    const start = Date.now();

    await userRequest(1);

    const elapsed = Date.now() - start;
    if (elapsed < 500) {
      await new Promise((resolve) => setTimeout(resolve, 500 - elapsed));
    }

    setIsRefreshing(false); // Stop spinning
  };

  const handleCopy = (text) => {
    navigator.clipboard.writeText(text);
    toast.success("Address copied to clipboard!");
  };

  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
    handleReset();
  };

  const dateFormat = (date) => {
    try {
      const orgDate = new Date(date).toUTCString();
      // console.log('orgDate', orgDate)
      const hours = new Date(date).getUTCHours();
      const amOrPm = hours >= 12 ? "PM" : "AM";
      const formattedDate = orgDate.split(",")[1].split("GMT")[0] + amOrPm;
      return formattedDate;
    } catch (e) {
      return "Invalid Date Format";
    }
  };

  const handleClick = (row, type) => {
    if (WithdrawEdit == 0 && adminType == "SubAdmin") {
      if (type == "approve") {
        toast.warning("Access Denied: You do not have permission to approve this request");
      } else if (type == "reject") {
        toast.warning("Access Denied: You do not have permission to reject this request.");
      }
    } else if (WithdrawEdit == 1 || adminType == "SuperAdmin") {
      setSelectedRow(row);
      setType(type);
      setShowModal(true);
    }
  };

  const Confirmation = async () => {
    if (selectedRow) {
      await handleAction(selectedRow, type);
    }
    setShowModal(false);
  };

  const handleClose = () => setShowModal(false);

  const columnsone = [
    {
      name: "S.No",
      selector: (row, index) => (currentPage - 1) * limit + index + 1,
      sortable: true,
      width: "75px",
    },
    {
      name: "Email",
      selector: (row) => row.userData.email || "--",
      sortable: true,
    },
    {
      name: "To Address",
      selector: (row) => row.toaddress || "--",
      sortable: true,
      cell: (row) => (
        <div className="d-flex align-items-center gap-2">
          <span className="text-truncate" style={{ maxWidth: "180px" }}>
            {row.toaddress || "--"}
          </span>
          {row.toaddress && (
            <FaRegCopy
              className="copy-icon"
              style={{ cursor: "pointer" }}
              onClick={() => handleCopy(row.toaddress)}
            />
          )}
        </div>
      ),
    },
    {
      name: "Currency",
      selector: (row) => row.moveCur || "--",
      sortable: true,
      width: "100px",
    },
    // {
    //     name: 'TX-Hash',
    //     selector: row => row.txnId || "-",
    //     sortable: true,
    // },
    {
      name: "Amount",
      selector: (row) =>
        userpower(formatWithoutRounding(userpower(row.amount), 8)) || "--",
      sortable: true,
      width: "100px",
    },
    {
      name: "Fees",
      selector: (row) => row.fees ? 
        userpower(formatWithoutRounding(userpower(row?.fees), 8)) : "--",
      sortable: true,
      width: "250px",
    },
    {
      name: "Date(UTC)",
      selector: (row) => dateFormat(row.createdDate) || "--",
      sortable: true,
      width: "200px",
    },
    {
      name: "Action",
      cell: (row) => (
        <div className="d-flex align-items-center gap-3">
          {/* {loading ? (
            <button
              className="d-send-btn-1 Aproved custom-main-button rounded-pill"
              type="button"
            >
              <Spinner animation="border" />
            </button>
          ) : (
            <> */}
          <button
            className="Aproved custom-main-button"
            onClick={() => handleClick(row, "approve")}
          >
            Approve
          </button>
          <button
            className="reject custom-main-button"
            onClick={() => handleClick(row, "reject")}
          >
            Reject
          </button>
          {/* </>
          )} */}
        </div>
      ),
      width: "300px",
    },
  ];

  async function handleAction(data, type) {
    try {
      setLoading(true);

      const address = await axios.get("https://api.ipify.org/?format=json");

      const lastloginIpAddress = address.data.ip;

      let userDatas = {
        ip: lastloginIpAddress,
        id: data._id,
        userId: data.userId,
        toaddress: data.toaddress,
        amount: data.amount,
        fees: data.fees,
        symbol: data.moveCur,
        type: type,
        reason: reason
      };
      let params = {
        url: "admin-withdrawalProcess",
        method: "POST",
        data: userDatas,
      };

      const withdrawEncryptres = await makeApiRequest(params);
      // console.log("withdrawalProcess===", withdrawEncryptres);  


      const withdrawdecryptedRes = decryptData(withdrawEncryptres.data);
      //  console.log("withdrawdecryptedRes", withdrawdecryptedRes);


      setLoading(false);
      if (withdrawdecryptedRes.status == true) {

        toast.success(withdrawdecryptedRes.message);
        setTimeout(() => {
          window.location.reload();
        }, 1000);
      } else {
        setLoading(true);
        toast.warning(withdrawdecryptedRes.message);
        setTimeout(() => {
          setLoading(false);

        }, 2000);
      }
    } catch (error) {
      setLoading(false);
      console.log("error----", error);
    }
  }

  const customStyles = {
    control: (base, state) => ({
      ...base,
      borderColor: state.isFocused ? "var(--color-1)" : "var(--color-1)",
      boxShadow: state.isFocused ? "0 0 0 1px var(--color-1)" : "none",
      borderRadius: "8px",
      fontSize: "13px",
      "&:hover": {
        borderColor: "var(--color-1)",
      },
      minWidth: "140px",
    }),
    menu: (base) => ({
      ...base,
      borderRadius: "8px",
      marginTop: 4,
    }),
    singleValue: (base) => ({
      ...base,
      color: "#000",
    }),
    option: (base, state) => ({
      ...base,
      backgroundColor: state.isSelected
        ? "var(--color-1)"
        : state.isFocused
          ? "#58f9b07c"
          : "white",
      color: state.isSelected ? "var(--theme-text-1)" : "black",
      ":active": {
        backgroundColor: "var(--color-1)",
      },
      cursor: "pointer",
      fontSize: "13px",
    }),
    menuPortal: (base) => ({
      ...base,
      zIndex: 9999,
    }),
  };

  return (
    <div className="App text-dark">
      <ToastContainer />
      <div className="container-fluid">
        <Modal
          show={showModal}
          onHide={handleClose}
          backdrop="static"
          keyboard={false}
          centered
        >
          <Modal.Header closeButton>
            <Modal.Title>Confirm {type}</Modal.Title>
          </Modal.Header>
          <Modal.Body className="text-capitalize mt-3">
            <p className="mb-1" style={type == "reject" ? { fontSize: "14px" } : {}}>Are you sure you want to {type} this User Transaction?</p>
            {type == "reject" ?
              <input type="text"
                placeholder="Enter a Reason"
                className="form-control input-form py-2"
                value={reason}
                onChange={(e) => {
                  setReason(e.target.value)
                }}></input>
              :
              <></>}
          </Modal.Body>
          <Modal.Footer className="border-0">
            <Button variant="secondary" onClick={handleClose}>
              Cancel
            </Button>

            {loading == true ? (
              <Button variant="success" style={{ width: "90px" }}>
                <Spinner size="sm" animation="border" />
              </Button>
            ) : (
              <>
                {type == "reject" && reason ? (
                  <Button
                    variant="success"
                    className="text-capitalize"
                    onClick={Confirmation}
                  >
                    {type}
                  </Button>
                ) : (
                  <>
                    {type == "reject" ? (
                      <Button
                        variant="success"
                        className="text-capitalize"
                        disabled
                      >
                        {type}
                      </Button>
                    ) : (
                      <Button
                        variant="success"
                        className="text-capitalize"
                        onClick={Confirmation}
                      >
                        {type}
                      </Button>
                    )}
                  </>
                )}
              </>
            )}
          </Modal.Footer>
        </Modal>
        <h3>User Withdraw Request</h3>
        <div className="row">
          <div className="d-flex calendor-form align-items-end gap-lg-4 flex-wrap">
            <div>
              <label for="email" className="form-label">
                Email
              </label>
              <input
                type="text"
                placeholder="Search by email or Address"
                className="form mb-3 search-bar form-control"
                value={searchQuery}
                onChange={handleSearchChange}
                style={{ width: "280px" }}
              />
            </div>
            <div className="mb-3">
              <label for="exampleInputPassword1" className="form-label">
                Currency
              </label>
              <Select
                options={cryptoOptions}
                value={
                  selectedSymbol
                    ? cryptoOptions.find(
                      (option) => option.value === selectedSymbol
                    )
                    : null
                }
                onChange={handleChange}
                id="border-css"
                isClearable
                styles={customStyles}
                isSearchable={false}
                components={{
                  IndicatorSeparator: () => null,
                }}
              />
            </div>
            <div className="mb-3">
              <label for="exampleInputPassword1" className="form-label">
                Date
              </label>

              <div
                ref={calendarRef}
                style={{ position: "relative", width: "250px" }}
              >
                <div
                  onClick={() => {
                    setShowCalendar(!showCalendar);
                    handleReset();
                  }}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    padding: "6px",
                    border: "1px solid var(--color-1)",
                    borderRadius: "5px",
                    cursor: "pointer",
                    backgroundColor: "#fff",
                    fontSize: "14px",
                  }}
                >
                  <span>
                    {fromDate && toDate
                      ? `${fromDate} - ${toDate}`
                      : "Select Date Range"}
                  </span>
                  <FaCalendarAlt style={{ color: "#555" }} />
                </div>
                {showCalendar && (
                  <div
                    style={{
                      position: "absolute",
                      top: "100%",
                      left: -80,
                      zIndex: 1000,
                      background: "#fff",
                      boxShadow: "0px 4px 6px rgba(0,0,0,0.1)",
                      borderRadius: "5px",
                    }}
                  >
                    <DateRange
                      editableDateInputs={true}
                      onChange={handleDateChange}
                      moveRangeOnFirstSelection={false}
                      ranges={range}
                      locale={enUS}
                      rangeColors={["#58f9b0"]}
                    />
                  </div>
                )}
              </div>
            </div>
            <div className="mb-2">
              <button
                type="button"
                className="form-label custom-nav-button-1 active cursor-pointer"
                onClick={handleClearFilters}
                disabled={isRefreshing}
              >
                <MdRefresh
                  style={{ fontSize: "24px" }}
                  className={isRefreshing ? "rotate-icon" : ""}
                />
              </button>
            </div>
          </div>

          <div className="col-lg-12">
            <div className="liquidity-table-1">
              <DataTable
                key={is_Refreshing}
                columns={columnsone}
                data={userData}
                theme="solarized"
                defaultSortAsc={true}
                pagination
                paginationServer
                persistTableHead
                paginationPerPage={limit}
                paginationTotalRows={totalItems}
                paginationRowsPerPageOptions={[5, 10, 15]}
                paginationResetDefaultPage={resetPaginationToggle}
                onChangeRowsPerPage={(newRowsPerPage) => {
                  setLimit(newRowsPerPage);
                  setCurrentPage(1);
                }}
                onChangePage={(page) => setCurrentPage(page)}
                progressPending={historyLoading}
                progressComponent={
                  <div className="py-4 w-100" style={{ marginLeft: "45vw" }}>
                    <Spinner animation="border" />
                  </div>
                }
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Withdrawrequest;
